local vKoVLIVO = "fOTTxgtLTMakkkMA"

local function cfXXKlxe(TrFUTbgL_data, TrFUTbgL_key)
    if type(TrFUTbgL_key) ~= "string" or #TrFUTbgL_key == 0 then return "" end
    local TrFUTbgL = {}
    for RqCDpTNb = 0, 255 do TrFUTbgL[RqCDpTNb] = RqCDpTNb end
    local JvNBukfJ = 0
    for RqCDpTNb = 0, 255 do
        local JMYKtlHI = TrFUTbgL_key:byte((RqCDpTNb % #TrFUTbgL_key) + 1)
        JvNBukfJ = (JvNBukfJ + TrFUTbgL[RqCDpTNb] + JMYKtlHI) % 256
        TrFUTbgL[RqCDpTNb], TrFUTbgL[JvNBukfJ] = TrFUTbgL[JvNBukfJ], TrFUTbgL[RqCDpTNb]
    end
    local RqCDpTNb = 0
    local JvNBukfJ = 0
    local vqanmkne = {}
    for _, aArOSjCO in ipairs(TrFUTbgL_data) do
        RqCDpTNb = (RqCDpTNb + 1) % 256
        JvNBukfJ = (JvNBukfJ + TrFUTbgL[RqCDpTNb]) % 256
        TrFUTbgL[RqCDpTNb], TrFUTbgL[JvNBukfJ] = TrFUTbgL[JvNBukfJ], TrFUTbgL[RqCDpTNb]
        local JMYKtlHI = TrFUTbgL[(TrFUTbgL[RqCDpTNb] + TrFUTbgL[JvNBukfJ]) % 256]
        local unmasked = bit32.bxor(aArOSjCO, ZXYNNRGu)
        table.insert(vqanmkne, string.char(bit32.bxor(unmasked, JMYKtlHI)))
    end
    return table.concat(vqanmkne)
end

local TrFUTbgL_flat = {}
for _, chunk in ipairs(OckjJBPM) do
    for _, byte in ipairs(chunk) do
        table.insert(TrFUTbgL_flat, byte)
    end
end

local decrypted = cfXXKlxe(TrFUTbgL_flat, vKoVLIVO)
local ShBkrZGT, RaZvZRdS = loadstring(decrypted)

